/*
Builds a POST request to acquire a token from Larmia AS7.
Reads host/port/scheme/credentials from global.config, and stores host on msg.ip
so the next node can associate the token with that host.
*/

const cfg = global.get('config','persistent');
if(!cfg){ node.error('Missing global.config'); return null; }

const host = cfg.host;
const port = cfg.port && cfg.port !== 80 ? `:${cfg.port}` : '';
const scheme = cfg.scheme || 'http';

msg.ip = host; // used later when saving the token
msg.method = "POST";
msg.url = `${scheme}://${host}${port}/w-api/v1/accounts/gettoken`;
msg.headers = { "Content-Type": "application/json", Accept: "application/json" };
msg.payload = { Username: cfg.user, Password: cfg.pass };
msg.rejectUnauthorized = false; // set true if you use a valid TLS cert
return msg;

/*
Saves the received token (payload.Key) into global.larmiaAuth.tokens[host].
The host key is taken from msg.ip (set in the previous function).
*/

const ip = msg.ip || msg.host;
const key = msg.payload?.Key ?? msg.payload?.key ?? null;
if(!key){ node.error(`No token. status=${msg.statusCode}`); return null; }

let auth = global.get('larmiaAuth','persistent');
if(!auth || typeof auth !== 'object') auth = {};
if(!auth.tokens || typeof auth.tokens !== 'object') auth.tokens = {};

auth.tokens[ip] = key;

global.set('larmiaAuth', auth, 'persistent');

msg.payload = { ok:true, ip, tokenSaved:true };
return msg;

/*
Builds a GET request to retrieve points from Larmia AS7.
Reads host/port/scheme from global.config and the token from global.larmiaAuth.tokens[host].
*/

const cfg = global.get('config','persistent');
if(!cfg){ node.error('Missing global.config'); return null; }

const host = cfg.host;
const port = cfg.port && cfg.port !== 80 ? `:${cfg.port}` : '';
const scheme = cfg.scheme || 'http';

const auth = global.get('larmiaAuth','persistent') || {};
const token = auth?.tokens?.[host];
if(!token){ node.error(`No token for ${host}`); return null; }

msg.method = 'GET';
msg.url = `${scheme}://${host}${port}/h-api/openapi/points`;
msg.headers = { Accept: 'application/json', Authorization: `Bearer ${token}` };
msg.payload = null;
msg.ip = host;
return msg;

// === Store ONLY parsed points (no raw), keyed by PID ===
// Path: global.grossList.larmia_controller[ip].points
// Fields per point:
//   PID, Property, system, label, Description, unit, component, system id, component id, HASH
// + preserves: toStream ("Unknown" | true | false), deprecated (boolean)
// + updates: lastSeen (ISO timestamp) on every refresh

// ---------- Configuration switches ----------
const PREFER_BASE_COMPONENT = false; // true => "ST21:1" -> "ST21"
const STRICT_SYSTEM_ID = true;       // true => remove ALL non-alphanumerics from Property/System
const HASH_LOWERCASE_INPUT = false;  // true => lowercases "PID|Property" before hashing

// ---------- Helpers: group, component, pointname, ids, hash ----------

// Split "GroupName" -> {property, system}
function splitGroupName(group) {
  const parts = String(group || "").split("•").map(s => s.trim()).filter(Boolean);
  return {
    property: parts[0] || null,
    system: parts[1] || null
  };
}

// Normalize a component token:
// - Keep letters+digits (+ optional ":index"), then trim at "/" and "-" to take FIRST component
// - If dropIndex=true, remove ":index" (e.g., "ST21:1" -> "ST21")
function normalizeComponentToken(raw, { dropIndex = false } = {}) {
  if (!raw) return null;
  let core = String(raw).split("/")[0].split("-")[0].trim();     // cut at "/" and "-"
  if (dropIndex) core = core.replace(/:.*$/, "");               // drop ":index" if requested
  // Letters (incl. ÅÄÖ) + digits + optional ":digits"
  const m = core.match(/^[A-Za-zÅÄÖåäö]+[0-9]+(?::[0-9]+)?$/u);
  return m ? m[0] : null;
}

// Parse "PointName" -> {sysToken, component, description, label}
function parsePointName(pointName, { preferBaseComponent = false } = {}) {
  const label = String(pointName || "").trim();
  if (!label) return { sysToken: null, component: null, description: null, label: null };

  // Strip known technical prefixes
  let s = label.replace(/^(REG:|REG\.)\s*/i, "");

  // Primary pattern: "SYS-REST"
  let m = s.match(/^\s*([A-Za-z0-9]+)\s*-\s*(.+)$/u);
  if (m) {
    const sysToken = m[1];
    let rest = m[2].trim();

    // Leading component (with space) or stuck
    const compLeading = rest.match(/^([A-Za-zÅÄÖåäö]+[0-9:\/-]+)(?:\s+|$)/u);
    if (compLeading) {
      const compRaw = compLeading[1];
      const component = normalizeComponentToken(compRaw, { dropIndex: preferBaseComponent });
      const descTail = rest.slice(compLeading[0].length).trim();
      const description = descTail || null;
      return { sysToken, component, description, label };
    }

    const compStuck = rest.match(/^([A-Za-zÅÄÖåäö]+[0-9:]+)([A-Za-zÅÄÖåäö].*)$/u);
    if (compStuck) {
      const component = normalizeComponentToken(compStuck[1], { dropIndex: preferBaseComponent });
      const description = compStuck[2].trim() || null;
      return { sysToken, component, description, label };
    }

    // No explicit component → full rest is description
    return { sysToken, component: null, description: rest || null, label };
  }

  // Secondary pattern: "SYS Description"
  m = s.match(/^\s*([A-Za-z0-9]+)\s+(.*)$/u);
  if (m) {
    const sysToken = m[1];
    let description = (m[2] || "").trim() || null;

    if (description) {
      const m2 = description.match(/^([A-Za-zÅÄÖåäö]+[0-9:\/-]+)(?:\s+|$)/u);
      if (m2) {
        const component = normalizeComponentToken(m2[1], { dropIndex: preferBaseComponent });
        const rest = description.slice(m2[0].length).trim();
        description = rest || description;
        return { sysToken, component, description, label };
      }

      const m3 = description.match(/^([A-Za-zÅÄÖåäö]+[0-9:]+)([A-Za-zÅÄÖåäö].*)$/u);
      if (m3) {
        const component = normalizeComponentToken(m3[1], { dropIndex: preferBaseComponent });
        const rest = m3[2].trim();
        return { sysToken, component, description: rest || null, label };
      }
    }
    return { sysToken, component: null, description, label };
  }

  // Fallback: keep label; try to salvage start component
  const stuck = s.match(/^([A-Za-zÅÄÖåäö]+[0-9:\/-]+)(.*)$/u);
  if (stuck) {
    const component = normalizeComponentToken(stuck[1], { dropIndex: preferBaseComponent });
    const description = (stuck[2] || "").trim() || null;
    return { sysToken: null, component, description, label };
  }

  return { sysToken: null, component: null, description: null, label };
}

// Build a sanitized systemId (and componentId) friendly for keys:
function makeSystemId(property, system, { strict = true } = {}) {
  const prop = String(property || "");
  const sys  = String(system || "");
  if (!prop && !sys) return null;

  const clean = (v) =>
    (strict ? v.replace(/[^A-Za-z0-9]/g, "") : v.replace(/\s+/g, ""))
      .trim();

  const propClean = clean(prop);
  const sysClean  = clean(sys);

  if (propClean && sysClean) return `${propClean}_${sysClean}`;
  if (propClean) return `${propClean}_`;
  if (sysClean)  return `_${sysClean}`;
  return null;
}

// FNV-1a 32-bit hash → hex string
function fnv1a32Hex(input) {
  let str = String(input ?? "");
  let h = 0x811c9dc5; // offset basis
  for (let i = 0; i < str.length; i++) {
    h ^= str.charCodeAt(i);
    h = (h + ((h << 1) + (h << 4) + (h << 7) + (h << 8) + (h << 24))) >>> 0;
  }
  return ("00000000" + h.toString(16)).slice(-8);
}

// Build PID+Property hash
function buildPidPropertyHash(pid, property) {
  const norm = (v) => String(v ?? "").replace(/\s+/g, " ").trim();
  let base = `${norm(pid)}|${norm(property)}`;
  if (HASH_LOWERCASE_INPUT) base = base.toLowerCase();
  return fnv1a32Hex(base);
}

// ---------- Main: parse & store ----------

const ip = msg.ip || msg.host || (global.get('config','persistent')?.host) || 'unknownIp';
const inv = global.get('grossList','persistent') || {};
const config = global.get('config','persistent') || {};
const deviceId = config?.deviceId || config?.iotEdge?.deviceId || 'unknownDevice'; // informational only

inv.larmia_controller ??= {};
inv.larmia_controller[ip] ??= {};
const nodeObj = inv.larmia_controller[ip];

// Existing points (for preserving manual flags + user fields)
const existingPoints = nodeObj.points || {};

// 1) Read incoming list
const list = Array.isArray(msg?.payload?.List) ? msg.payload.List : [];

// 2) Build parsed-only points (key = PID)
const parsedPoints = {};
let saved = 0;

// Timestamp for this refresh (same for all points in this run)
const nowIso = new Date().toISOString();

for (const p of list) {
  const PID = String(p?.PID ?? "");
  if (!PID) continue;

  const prev = existingPoints[PID] || {};

  const { property, system } = splitGroupName(p?.GroupName);
  const { component, description, label } = parsePointName(
    p?.PointName,
    { preferBaseComponent: PREFER_BASE_COMPONENT }
  );

  const unit = p?.Unit ?? null;

  const systemId = makeSystemId(property, system, { strict: STRICT_SYSTEM_ID });
  const componentId = (systemId && component) ? `${systemId}_${component}` : null;

  const pidPropertyHash = buildPidPropertyHash(PID, property);

  parsedPoints[PID] = {
    PID,
    Property: property || null,
    system: system || null,
    label: label || null,
    Description: description || null,
    unit: unit,
    component: component || null,
    "system id": systemId,
    "component id": componentId,
    "HASH": pidPropertyHash,

    // Preserve if already set; otherwise defaults
    toStream: (prev.toStream !== undefined) ? prev.toStream : "Unknown", // "Unknown" | true | false
    deprecated: (prev.deprecated !== undefined) ? prev.deprecated : false,

    // Always updated on refresh
    lastSeen: nowIso,

    // Keep existing location fields if they were manually populated
    floor: prev.floor ?? "",
    zone: prev.zone ?? "",
    room: prev.room ?? ""
  };

  saved++;
}

// 3) Save ONLY parsed points (replace previous .points entirely)
nodeObj.points = parsedPoints;
inv.larmia_controller[ip] = nodeObj;

global.set('grossList', inv, 'persistent');

// 4) Output
msg.payload = {
  ok: true,
  ip,
  deviceId,
  savedPoints: saved,
  totalPoints: Object.keys(parsedPoints).length,
  lastSeen: nowIso
};

msg.points = parsedPoints;
return msg;
